package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class CommentTests {
 static int checks;static void check(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
 static String notes(Document d){ArrayList<String> n=new ArrayList<>();for(Node b:d.nodes)if(b.comment!=null&&!b.comment.isEmpty())n.add(b.comment);Collections.sort(n);return String.join("|",n);}
 static String run(Document d){FlowEngine.Runner r=new FlowEngine.Runner(d);for(int i=0;i<500&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++)r.step();check(r.state==FlowEngine.State.COMPLETED,"Execution completes: "+r.errorMessage);return String.join("|",r.output);}
 static void reject(String s){boolean rejected=false;try{FlowPseudocode.decode(s);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Invalid note rejected");}
 static void save(Path p,String text)throws Exception{Files.write(p,text.getBytes(StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception{Path out=Paths.get(args[0]);
  Document pc=FlowCodec.decode(new String(Files.readAllBytes(out.resolve("pc-comments.frociart")),StandardCharsets.UTF_8));check(run(pc).equals("2"),"PC file with annotations runs on Android");check(notes(pc).equals(notes(pc.copy())),"Document copy retains notes");check(notes(pc).equals(notes(FlowCodec.decode(FlowCodec.encode(pc)))),"Android codec keeps exact notes");check(notes(pc).equals(notes(FlowPseudocode.decode(FlowPseudocode.encode(pc)))),"Android pseudocode roundtrip keeps exact notes");
  save(out.resolve("android-comments.frociart"),FlowCodec.encode(pc));save(out.resolve("android-comments.txt"),FlowPseudocode.encode(pc));
  check(!FlowCodec.encode(FlowPseudocode.decode("STAMPA 1")).contains("Comment"),"Legacy file omits optional metadata");
  Document implicit=FlowPseudocode.decode("NOTA \"operazione\"\nx=1\nSTAMPA x");for(Node b:implicit.nodes)if(b.kind==PROCESS)check("operazione".equals(b.comment),"Implicit start does not steal note");
  for(String s:new String[]{"NOTA \"senza blocco\"","NOTA x\nx=1","NOTA \"a\"+\"b\"\nx=1","NOTA \"a\"\nFUNZIONE f()\nFINE FUNZIONE\nSTAMPA 1","SE vero ALLORA\nNOTA \"a\"\nFINE SE\nFINE","NOTA \""+String.join("",Collections.nCopies(2049,"x"))+"\"\nx=1"})reject(s);
  for(String s:new String[]{"INIZIO\nPER i DA 1 A 2 FAI\nSTAMPA i\nFINE PER\nFINE","INIZIO\nx=0\nMENTRE x < 2 FAI\nx=x+1\nFINE MENTRE\nSTAMPA x\nFINE","FUNZIONE doppio(n: INTERO) -> INTERO risultato\nrisultato=n*2\nFINE FUNZIONE\nINIZIO\nSTAMPA doppio(3)\nFINE"}){Document d=FlowPseudocode.decode(s);ArrayList<Document> graphs=new ArrayList<>();graphs.add(d);if(d.functions!=null)for(Function f:d.functions)graphs.add(f.body);for(Document g:graphs)for(int i=0;i<g.nodes.size();i++)g.nodes.get(i).comment="nota "+i;Document q=FlowPseudocode.decode(FlowPseudocode.encode(d));check(notes(d).equals(notes(q))&&run(d).equals(run(q)),"Cycles and functions keep notes");if(d.functions!=null)check(notes(d.functions.get(0).body).equals(notes(q.functions.get(0).body)),"Function notes retained");}
  Document separated=pc.copy();Node loose=new Node(PROCESS,"unused=1",0,0);loose.comment="scollegato";separated.nodes.add(loose);check(notes(separated).equals(notes(FlowPseudocode.decode(FlowPseudocode.encode(separated)))),"Disconnected notes retained");
  FlowSource.Program model=FlowSource.compile(pc);pc.nodes.get(0).comment="mutated";check(!model.scopes.get(0).blocks.get(0).comment.equals("mutated"),"Source snapshot freezes annotations");String jr=new String(Files.readAllBytes(out.resolve("../frociart-v1-capabilities/pc/Source/JavaRuntime.txt")),StandardCharsets.UTF_8),pr=new String(Files.readAllBytes(out.resolve("../frociart-v1-capabilities/pc/Source/PythonRuntime.py")),StandardCharsets.UTF_8);String java=FlowJava.generate(model,jr,"CommentProgram").text,python=FlowPython.generate(model,pr).text;save(out.resolve("android-CommentProgram.java"),java);save(out.resolve("android-comments.py"),python);check(java.equals(new String(Files.readAllBytes(out.resolve("CommentProgram.java")),StandardCharsets.UTF_8)),"Identical Java on both platforms");check(python.equals(new String(Files.readAllBytes(out.resolve("comments.py")),StandardCharsets.UTF_8)),"Identical Python on both platforms");
  Node measured=pc.nodes.get(1);measured.comment="Spiegazione\nSeconda riga\nTerza riga";float h=height(measured);measured.comment=null;check(h>height(measured),"Geometry grows with note");measured.previewComment="Bozza";check(measured.displayText().contains("Bozza")&&measured.copy().previewComment==null,"Visual preview is transient");measured.comment=String.join("",Collections.nCopies(2049,"x"));boolean limit=false;try{FlowCodec.encode(pc);}catch(IllegalArgumentException e){limit=true;}check(limit,"File limit rejects excess note");System.out.println("COMMENTS_ANDROID PASS checks="+checks);
 }
}
